package vip.xiaonuo.srm.quality;
import java.util.*;import java.time.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.annotation.*;import vip.xiaonuo.srm.api.*;import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;import vip.xiaonuo.srm.performance.api.SrmRiskApi;import vip.xiaonuo.srm.collaboration.api.SrmCollaborationRiskApi;import static vip.xiaonuo.srm.quality.QualityStore.*;import static vip.xiaonuo.srm.quality.QualityInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED) public class QualityRisks implements SrmRiskApi {
 final QualityStore x;final SrmCollaborationRiskApi collaboration;final SrmLifecycleProposalApi lifecycle;
 void internal(Context a){x.readable(a);require(!a.portal(),403,"内部风险评估不可由门户访问");}
 public Map<String,Object> create(Context a,Risk p){x.sqe(a);x.event(a,p.supplierId(),"COMPLIANCE_BLACKLIST","manual:"+a.orgId()+":"+p.requestKey(),"MANUAL",Map.of("description",p.description(),"evidenceRef",p.evidenceRef()));var r=x.db.queryForMap("SELECT ID,BASIS_CIPHER FROM SRM_QL_RISK WHERE EVENT_KEY=?","manual:"+a.orgId()+":"+p.requestKey());require(x.hash(x.object(x.crypto.decrypt(s(r,"BASIS_CIPHER")))).equals(x.hash(Map.of("description",p.description(),"evidenceRef",p.evidenceRef()))),409,"请求号内容冲突");return detail(a,s(r,"ID"));}
 public Map<String,Object> page(Context a,int current,int size){internal(a);require(current>=1&&size>=1&&size<=100,400,"分页无效");var args=new ArrayList<Object>();String w=x.where(a,args,"r");long total=x.db.queryForObject("SELECT COUNT(*) FROM SRM_QL_RISK r WHERE "+w,Long.class,args.toArray());args.add(size);args.add((current-1)*size);return Map.of("total",total,"records",x.db.queryForList("SELECT r.ID AS id,r.RISK_TYPE AS riskType,r.STATUS AS status,r.LEVEL AS level,r.SOURCE AS source,r.ROW_VERSION AS rowVersion,r.FREEZE_SUGGESTED AS freezeSuggested,r.FREEZE_APPROVAL_ID AS freezeApprovalId,s.NAME AS supplierName FROM SRM_QL_RISK r JOIN SRM_SUPPLIER s ON s.ID=r.SUPPLIER_ID WHERE "+w+" ORDER BY r.UPDATED_AT DESC,r.ID DESC LIMIT ? OFFSET ?",args.toArray()));}
 public Map<String,Object> detail(Context a,String id){internal(a);var r=x.row(a,"SRM_QL_RISK",id,false);var o=new LinkedHashMap<String,Object>();for(String[] f:new String[][]{{"id","ID"},{"supplierId","SUPPLIER_ID"},{"riskType","RISK_TYPE"},{"source","SOURCE"},{"status","STATUS"},{"level","LEVEL"},{"rowVersion","ROW_VERSION"},{"freezeSuggested","FREEZE_SUGGESTED"},{"freezeApprovalId","FREEZE_APPROVAL_ID"}})o.put(f[0],r.get(f[1]));o.put("basis",x.object(x.crypto.decrypt(s(r,"BASIS_CIPHER"))));o.put("assessment",r.get("ASSESSMENT_CIPHER")==null?"":x.crypto.decrypt(s(r,"ASSESSMENT_CIPHER")));var actions=new ArrayList<Map<String,Object>>();for(var action:x.db.queryForList("SELECT * FROM SRM_QL_RISK_ACTION WHERE RISK_ID=? ORDER BY CREATED_AT,ID",id))actions.add(Map.of("action",action.get("ACTION"),"content",x.object(x.crypto.decrypt(s(action,"CONTENT_CIPHER"))),"createdAt",action.get("CREATED_AT")));o.put("history",actions);return o;}
 void action(Context a,String id,String action,Object data){x.db.update("INSERT INTO SRM_QL_RISK_ACTION VALUES(?,?,?,?,?,NOW(3))",id(),id,action,a.userId(),x.crypto.encrypt(x.json(data)));}
 public Map<String,Object> assess(Context a,String id,Assess p){x.sqe(a);var r=x.row(a,"SRM_QL_RISK",id,true);x.version(r,p.rowVersion());require(!s(r,"STATUS").equals("DISPOSED"),409,"已归档事件不可重写");x.db.update("UPDATE SRM_QL_RISK SET LEVEL=?,STATUS=?,ASSESSMENT_CIPHER=?,ASSESSED_BY=?,FREEZE_SUGGESTED=?,ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",p.level(),p.level().equals("LOW")?"ASSESSED":"WARNING",x.crypto.encrypt(p.comment()),a.userId(),p.level().equals("HIGH"),id);action(a,id,"ASSESSED",Map.of("level",p.level(),"comment",p.comment()));x.notice(r,p.level().equals("HIGH")?"高风险已生成经理冻结建议待办，请评审处理":"内部风险等级已评估，请按意见跟进",id+":assess:"+(n(r,"ROW_VERSION")+1),false);x.audit(a,r,"RISK_ASSESSED");return detail(a,id);}
 public Map<String,Object> freeze(Context a,String id,Assess p){x.manager(a);var r=x.row(a,"SRM_QL_RISK",id,true);x.version(r,p.rowVersion());require(s(r,"LEVEL").equals("HIGH")&&!s(r,"STATUS").equals("DISPOSED"),409,"只有未归档高风险可发起冻结审批");if(r.get("FREEZE_APPROVAL_ID")==null){var approval=lifecycle.proposeFreeze(a,s(r,"SUPPLIER_ID"),"risk_"+id,"内部风险"+id+"；"+p.comment().substring(0,Math.min(900,p.comment().length())));x.db.update("UPDATE SRM_QL_RISK SET FREEZE_APPROVAL_ID=?,ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",approval.get("id"),id);action(a,id,"FREEZE_APPROVAL_SUBMITTED",Map.of("approvalId",approval.get("id"),"comment",p.comment()));}return detail(a,id);}
 public Map<String,Object> dispose(Context a,String id,Dispose p){x.sqe(a);var r=x.row(a,"SRM_QL_RISK",id,true);x.version(r,p.rowVersion());require(r.get("LEVEL")!=null&&!s(r,"STATUS").equals("DISPOSED"),409,"须先评估，已归档记录不可重写");if(s(r,"LEVEL").equals("HIGH"))x.manager(a);if(p.action().equals("APPROVAL_SUBMITTED"))require(r.get("FREEZE_APPROVAL_ID")!=null,409,"尚未发起冻结审批");x.db.update("UPDATE SRM_QL_RISK SET STATUS='DISPOSED',ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",id);action(a,id,"DISPOSED",Map.of("action",p.action(),"comment",p.comment(),"evidenceRef",p.evidenceRef()));x.audit(a,r,"RISK_DISPOSED");return detail(a,id);}
 public Map<String,Object> summary(String org,String sid){var supplier=x.access.requireSupplier(x.system(org,"SYSTEM"),sid,false);require(org.equals(supplier.orgId()),404,"供应商组织不一致");var rows=x.db.queryForList("SELECT ID,LEVEL,STATUS,ROW_VERSION FROM SRM_QL_RISK WHERE ORG_ID=? AND SUPPLIER_ID=? AND STATUS<>'DISPOSED' ORDER BY ID",org,sid);String level="UNKNOWN";if(rows.stream().anyMatch(r->s(r,"LEVEL").equals("HIGH")))level="HIGH";else if(rows.stream().anyMatch(r->r.get("LEVEL")==null))level="UNKNOWN";else if(!rows.isEmpty())level=rows.stream().anyMatch(r->s(r,"LEVEL").equals("MEDIUM"))?"MEDIUM":"LOW";return Map.of("source","INTERNAL_LEDGER","level",level,"basis",rows,"basisHash",x.hash(rows),"hasEvents",!rows.isEmpty(),"notice",rows.isEmpty()?"暂无未归档内部风险，仍需核对人工评估和外部依据":"内部风险事件与评估快照");}
 @Scheduled(fixedDelay=30000) public void ingest(){for(var supplier:x.db.queryForList("SELECT ID,ORG_ID FROM SRM_SUPPLIER WHERE DELETE_FLAG='NOT_DELETE' ORDER BY ID LIMIT 2000")){String sid=s(supplier,"ID"),org=s(supplier,"ORG_ID");var a=x.system(org,"SYSTEM");for(var e:collaboration.pending(org,sid))x.event(a,sid,"DELIVERY_EXCEPTION","collab:"+e.get("id"),"COLLABORATION",e);for(var cert:x.db.queryForList("SELECT ID,CERT_TYPE,VALID_TO FROM SRM_SUPPLIER_CERT WHERE SUPPLIER_ID=? AND STATUS<>'VOID' AND DELETE_FLAG='NOT_DELETE' AND VALID_TO<?",sid,LocalDate.now(ZoneId.of("Asia/Shanghai"))))x.event(a,sid,"CERTIFICATE_EXPIRED","certificate:"+cert.get("ID"),"CERTIFICATE",Map.of("certificateId",cert.get("ID"),"certType",cert.get("CERT_TYPE"),"validTo",String.valueOf(cert.get("VALID_TO"))));}
  for(var first:x.db.queryForList("SELECT * FROM SRM_QL_CASE WHERE KIND='SCAR' AND STATUS NOT IN ('CLOSED','REJECTED') ORDER BY SUPPLIER_ID,ID LIMIT 1000")){var a=x.system(s(first,"ORG_ID"),"SYSTEM");var r=x.row(a,"SRM_QL_CASE",s(first,"ID"),true);var config=(Map<?,?>)x.object(x.crypto.decrypt(s(r,"META_CIPHER"))).get("policy");boolean overdue=QualityRules.responseOverdue(s(r,"STATUS"),n(r,"DUE_MS"),System.currentTimeMillis());long repeats=x.db.queryForObject("SELECT COUNT(*) FROM SRM_QL_CASE WHERE KIND='SCAR' AND SUPPLIER_ID=? AND DEFECT_KEY=? AND CREATED_AT>=DATE_SUB(NOW(3),INTERVAL ? DAY)",Long.class,r.get("SUPPLIER_ID"),r.get("DEFECT_KEY"),config.get("repeatWindowDays"));if(overdue||repeats>1){if(overdue&&!s(r,"STATUS").equals("ESCALATED"))x.db.update("UPDATE SRM_QL_CASE SET STATUS='ESCALATED',ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",r.get("ID"));x.event(a,s(r,"SUPPLIER_ID"),overdue?"SCAR_OVERDUE":"REPEATED_DEFECT","scar:"+r.get("ID")+":"+(overdue?"overdue":"repeat"),"QUALITY",Map.of("scarId",r.get("ID"),"defectKey",r.get("DEFECT_KEY"),"repeatCount",repeats,"dueAt",r.get("DUE_MS")));x.notice(r,"SCAR超期或重复缺陷已升级，请质量联系人跟进",s(r,"ID")+":escalated",true);}}
 }
 public Map<String,Object> policy(Context a){x.sqe(a);return x.policy(a.orgId());}public Map<String,Object> publishPolicy(Context a,Policy p){x.manager(a);x.db.queryForList("SELECT ID FROM SYS_ORG WHERE ID=? FOR UPDATE",a.orgId());var current=x.policy(a.orgId());require(((Number)current.get("version")).longValue()==p.expectedVersion(),409,"策略版本变化");require(p.minorDeduction().compareTo(p.majorDeduction())<=0&&p.majorDeduction().compareTo(p.severeDeduction())<=0,400,"扣分应随严重性递增");x.db.update("INSERT INTO SRM_QL_POLICY VALUES(?,?,?,?,?,?,NOW(3))",id(),a.orgId(),p.expectedVersion()+1,x.json(p),p.reason(),a.userId());return x.policy(a.orgId());}
 public List<Map<String,Object>> notices(Context a){var args=new ArrayList<Object>();String w=x.where(a,args,"n")+(a.portal()?" AND n.AUDIENCE='PORTAL'":" AND n.AUDIENCE='SQE'");return x.db.queryForList("SELECT ID AS id,BUSINESS_ID AS businessId,MESSAGE AS message,CREATED_AT AS createdAt FROM SRM_QL_NOTICE n WHERE "+w+" ORDER BY CREATED_AT DESC LIMIT 100",args.toArray());}
}
